public class DOMNodePointer_getLanguage_TriageGen1Test {

    /**
     * Helper method to access the protected getLanguage method via reflection
     */
    private String invokeGetLanguage(DOMNodePointer pointer) throws Exception {
        Method method = DOMNodePointer.class.getDeclaredMethod("getLanguage");
        method.setAccessible(true);
        return (String) method.invoke(pointer);
    }

    @Test
    public void testGetLanguage_NullNode() throws Exception {
        // Constructor with null node
        DOMNodePointer pointer = new DOMNodePointer(null, Locale.ENGLISH);
        assertNull(invokeGetLanguage(pointer));
    }

    @Test
    public void testGetLanguage_ElementWithLangAttribute() throws Exception {
        Node mockElement = mock(Element.class);
        when(mockElement.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(mockElement.getAttribute("xml:lang")).thenReturn("en");
        when(mockElement.getParentNode()).thenReturn(null);

        DOMNodePointer pointer = new DOMNodePointer(mockElement, Locale.ENGLISH);
        assertEquals("en", invokeGetLanguage(pointer));
    }

    @Test
    public void testGetLanguage_ElementWithEmptyLangAttribute() throws Exception {
        // Current node is element but attribute is empty, should check parent
        Node mockElement = mock(Element.class);
        when(mockElement.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(mockElement.getAttribute("xml:lang")).thenReturn("");

        Node mockParent = mock(Element.class);
        when(mockParent.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(mockParent.getAttribute("xml:lang")).thenReturn("fr");
        when(mockParent.getParentNode()).thenReturn(null);

        when(mockElement.getParentNode()).thenReturn(mockParent);

        DOMNodePointer pointer = new DOMNodePointer(mockElement, Locale.ENGLISH);
        assertEquals("fr", invokeGetLanguage(pointer));
    }

    @Test
    public void testGetLanguage_ElementWithNullLangAttribute() throws Exception {
        // Current node is element but attribute is null, should check parent
        Node mockElement = mock(Element.class);
        when(mockElement.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(mockElement.getAttribute("xml:lang")).thenReturn(null);

        Node mockParent = mock(Element.class);
        when(mockParent.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(mockParent.getAttribute("xml:lang")).thenReturn("de");
        when(mockParent.getParentNode()).thenReturn(null);

        when(mockElement.getParentNode()).thenReturn(mockParent);

        DOMNodePointer pointer = new DOMNodePointer(mockElement, Locale.ENGLISH);
        assertEquals("de", invokeGetLanguage(pointer));
    }

    @Test
    public void testGetLanguage_NonElementNodeTraversingToElement() throws Exception {
        // Current node is a TEXT_NODE, should skip and check parent which is an ELEMENT
        Node mockTextNode = mock(Node.class);
        when(mockTextNode.getNodeType()).thenReturn(Node.TEXT_NODE);

        Node mockParentElement = mock(Element.class);
        when(mockParentElement.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(mockParentElement.getAttribute("xml:lang")).thenReturn("es");
        when(mockParentElement.getParentNode()).thenReturn(null);

        when(mockTextNode.getParentNode()).thenReturn(mockParentElement);

        DOMNodePointer pointer = new DOMNodePointer(mockTextNode, Locale.ENGLISH);
        assertEquals("es", invokeGetLanguage(pointer));
    }

    @Test
    public void testGetLanguage_NoLangFoundInHierarchy() throws Exception {
        Node mockElement = mock(Element.class);
        when(mockElement.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(mockElement.getAttribute("xml:lang")).thenReturn("");

        Node mockParent = mock(Element.class);
        when(mockParent.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(mockParent.getAttribute("xml:lang")).thenReturn("");
        when(mockParent.getParentNode()).thenReturn(null);

        when(mockElement.getParentNode()).thenReturn(mockParent);

        DOMNodePointer pointer = new DOMNodePointer(mockElement, Locale.ENGLISH);
        assertNull(invokeGetLanguage(pointer));
    }

    @Test
    public void testGetLanguage_HierarchyWithMixedNodes() throws Exception {
        // Text -> Element (no lang) -> Text -> Element (has lang)
        Node text1 = mock(Node.class);
        when(text1.getNodeType()).thenReturn(Node.TEXT_NODE);

        Node elem1 = mock(Element.class);
        when(elem1.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(elem1.getAttribute("xml:lang")).thenReturn("");

        Node text2 = mock(Node.class);
        when(text2.getNodeType()).thenReturn(Node.TEXT_NODE);

        Node elem2 = mock(Element.class);
        when(elem2.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(elem2.getAttribute("xml:lang")).thenReturn("it");
        when(elem2.getParentNode()).thenReturn(null);

        when(text1.getParentNode()).thenReturn(elem1);
        when(elem1.getParentNode()).thenReturn(text2);
        when(text2.getParentNode()).thenReturn(elem2);

        DOMNodePointer pointer = new DOMNodePointer(text1, Locale.ENGLISH);
        assertEquals("it", invokeGetLanguage(pointer));
    }
}
